function createChildrenExampleNode (
  childrenModeType: ChildrenViewModeTypes
) {
  return createChildrenNode({
    nodeConfig: {
      type: childrenModeType
    },
    children: [
      createTextNode({
        nodeConfig: {
          contentType: "html",
          content: "Dummy Child Node 1"
        },
        layoutData: {
          forParent: {
            grid: {
              row: 1,
              col: 1,
              rowSpan: 1,
              colSpan: 1
            }
          }
        }
      }),
      createTextNode({
        nodeConfig: {
          contentType: "html",
          content: "Dummy Child Node 2"
        },
        layoutData: {
          forParent: {
            grid: {
              row: 1,
              col: 2,
              rowSpan: 1,
              colSpan: 1
            }
          }
        }
      }),
      createTextNode({
        nodeConfig: {
          contentType: "html",
          content: "Dummy Child Node 3"
        },
        layoutData: {
          elementProps: {
            styleCss: childrenModeType === "grid"
              ? `
              background-color: green; 
              
              .text-node {
              justify-content: center; 
              display: flex;
              
              }`
              : ""
          },
          forParent: {
            grid: {
              row: 2,
              col: 1,
              rowSpan: 1,
              colSpan: 2
            }
          }
        }
      })
    ]
  });
}

function createTabsExampleNode (position: TabsNodeProps["position"], gridRow: number, gridColumn: number) {
  return createTabsNode({
    nodeConfig: {
      position: position
    },
    layoutData: {
      forParent: {
        grid: {
          row: gridRow,
          col: gridColumn,
          rowSpan: 1,
          colSpan: 1
        }
      }
    },
    children: [
      createTabNode({
        layoutData: {
          label: "Tab 1"
        },
        children: []
      }),
      createTabNode({
        layoutData: {
          label: "Tab 2"
        },
        children: []
      }),
      createTabNode({
        layoutData: {
          label: "Tab 3"
        },
        children: []
      })
    ]
  });
}

function createExampleLabel (label: string) {
  return createTextNode({
    nodeConfig: {
      contentType: "markdown",
      content: `## ${label}`
    }
  });
}

