export function staticNode (overrides: Partial<DashboardLayoutNode>): DashboardLayoutNode {
  return {
    id: nanoid(),
    createdAt: new Date().toISOString() as any,
    updatedAt: new Date().toISOString() as any,
    isDeleted: 0,
    layoutData: {},
    nodeConfig: {},
    ofTemplate: 0,
    order: 1,
    parentId: null,
    specialFlags: null,
    type: "children",
    children: [],
    ...overrides
  };
}

interface PossibleChanges<TNodeConfig> {
  id?: DashboardLayoutNode["id"] & string;
  nodeConfig?: TNodeConfig;
  layoutData?: DashboardLayoutNode["layoutData"];
}

interface WithChildren {
  children?: DashboardLayoutNode[];
}

// Button node
export function createButtonNode (changes: PossibleChanges<ButtonNodeProps>): DashboardLayoutNode {
  return staticNode({
    type: "button",
    ...changes
  });
}

// Tabs node
export function createTabsNode (changes: PossibleChanges<TabsNodeProps> & WithChildren): DashboardLayoutNode {
  return staticNode({
    type: "tabs",
    ...changes
  });
}

// Tab node (child of tabs)
